<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Auth,Csrf,Database,View};

final class InventarioController
{
 public function index():void {Auth::requireAdmin();$db=Database::connection();$tipo=$_GET['tipo']??'';$desde=$_GET['desde']??'';$hasta=$_GET['hasta']??'';$sql='SELECT mi.*,m.codigo,m.nombre,l.numero_lote,u.nombres usuario FROM movimientos_inventario mi JOIN medicamentos m ON m.id=mi.medicamento_id JOIN lotes l ON l.id=mi.lote_id JOIN usuarios u ON u.id=mi.usuario_id WHERE 1';$p=[];if(in_array($tipo,['entrada','ajuste_entrada','ajuste_salida','venta'],true)){$sql.=' AND mi.tipo=?';$p[]=$tipo;}if($desde){$sql.=' AND DATE(mi.creado_en)>=?';$p[]=$desde;}if($hasta){$sql.=' AND DATE(mi.creado_en)<=?';$p[]=$hasta;}$sql.=' ORDER BY mi.id DESC LIMIT 500';$s=$db->prepare($sql);$s->execute($p);$movimientos=$s->fetchAll();$lotes=$db->query('SELECT l.id,l.numero_lote,l.cantidad_disponible,m.nombre FROM lotes l JOIN medicamentos m ON m.id=l.medicamento_id ORDER BY m.nombre,l.fecha_vencimiento')->fetchAll();View::render('inventario/index',compact('movimientos','lotes','tipo','desde','hasta'));}
 public function ajuste():void {Auth::requireAdmin();Csrf::enforce();$db=Database::connection();$loteId=(int)($_POST['lote_id']??0);$tipo=$_POST['tipo']??'';$cantidad=filter_var($_POST['cantidad']??null,FILTER_VALIDATE_INT);$motivo=trim($_POST['motivo']??'');if(!$loteId||!in_array($tipo,['ajuste_entrada','ajuste_salida'],true)||$cantidad===false||$cantidad<1||mb_strlen($motivo)<4){flash('danger','Datos de ajuste inválidos.');redirect('index.php?page=inventario');}try{$db->beginTransaction();$s=$db->prepare('SELECT * FROM lotes WHERE id=? FOR UPDATE');$s->execute([$loteId]);$l=$s->fetch();if(!$l)throw new \RuntimeException('Lote no encontrado.');$anterior=(int)$l['cantidad_disponible'];$posterior=$tipo==='ajuste_entrada'?$anterior+$cantidad:$anterior-$cantidad;if($posterior<0)throw new \RuntimeException('El ajuste produciría stock negativo.');$db->prepare('UPDATE lotes SET cantidad_disponible=?,cantidad_inicial=GREATEST(cantidad_inicial,?) WHERE id=?')->execute([$posterior,$posterior,$loteId]);$signo=$tipo==='ajuste_entrada'?$cantidad:-$cantidad;$db->prepare('INSERT INTO movimientos_inventario(medicamento_id,lote_id,usuario_id,tipo,cantidad,stock_anterior,stock_posterior,motivo) VALUES(?,?,?,?,?,?,?,?)')->execute([$l['medicamento_id'],$loteId,Auth::id(),$tipo,$signo,$anterior,$posterior,$motivo]);$db->commit();flash('success','Ajuste registrado correctamente.');}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();flash('danger',$e->getMessage());}redirect('index.php?page=inventario');}
}
